import { lazy, Suspense, useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useNavigate, useLocation } from 'react-router-dom';
import Toast from './components/Toast';
import { SettingsProvider } from './contexts/SettingsContext';
import { ToastProvider } from './contexts/ToastContext';
import { HistoryProvider } from './contexts/HistoryContext';
import { AuthProvider } from './contexts/AuthContext';
import Navbar from './components/Navbar';
import Spinner from './components/Spinner';

// Lazy-load pages for code splitting
const Home = lazy(() => import('./pages/Home'));
const Browse = lazy(() => import('./pages/Browse'));
const MediaDetail = lazy(() => import('./pages/MediaDetail'));
const Watch = lazy(() => import('./pages/Watch'));
const Search = lazy(() => import('./pages/Search'));
const Streams = lazy(() => import('./pages/Streams'));
const Watchlist = lazy(() => import('./pages/Watchlist'));
const Settings = lazy(() => import('./pages/Settings'));
const NotFound = lazy(() => import('./pages/NotFound'));

function PageLoader() {
  return (
    <div className="flex items-center justify-center min-h-[60vh]">
      <Spinner size="lg" />
    </div>
  );
}

function RouterSetup() {
  const navigate = useNavigate();
  const location = useLocation();
  
  // Track page views for analytics/history
  useEffect(() => {
    window.dispatchEvent(new CustomEvent('pageview', { detail: { path: location.pathname, time: Date.now() } }));
  }, [location.pathname]);

  // Handle hash-based navigation fallback
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.slice(1);
      if (hash && hash !== location.pathname) {
        navigate(hash, { replace: true });
      }
    };
    
    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, [navigate, location.pathname]);

  return null;
}

function AppRoutes() {
  return (
    <>
      <Navbar />
      <Suspense fallback={<PageLoader />}>
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/browse" element={<Browse />} />
          <Route path="/movies/:id" element={<MediaDetail type="movie" />} />
          <Route path="/tv/:id" element={<MediaDetail type="tv" />} />
          <Route path="/watch/:type/:id" element={<Watch />} />
          <Route path="/:type/:id/streams" element={<Streams />} />
          <Route path="/watchlist" element={<Watchlist />} />
          <Route path="/settings" element={<Settings />} />
          <Route path="*" element={<NotFound />} />
        </Routes>
      </Suspense>
    </>
  );
}

function AppContent() {
  const [appReady, setAppReady] = useState(document.readyState === 'complete');
  
  useEffect(() => {
    if (document.readyState === 'complete') {
      setAppReady(true);
    } else {
      const handler = () => setAppReady(true);
      window.addEventListener('load', handler, { once: true });
      return () => window.removeEventListener('load', handler);
    }
  }, []);

  if (!appReady && document.readyState !== 'interactive') {
    return (
      <div className="min-h-screen bg-[#0a0a0f] flex items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0a0a0f] text-white">
      <RouterSetup />
      <AppRoutes />
      <Toast />
    </div>
  );
}

function App() {
  return (
    <AuthProvider>
      <SettingsProvider>
        <ToastProvider>
          <HistoryProvider>
            <Router>
              <AppContent />
            </Router>
          </HistoryProvider>
        </ToastProvider>
      </SettingsProvider>
    </AuthProvider>
  );
}

export default App;
