import { memo } from 'react';
import { Loader2 } from 'lucide-react';

interface SpinnerProps {
  size?: 'sm' | 'md' | 'lg' | 'xl';
  text?: string;
  fullScreen?: boolean;
}

const sizeClasses = {
  sm: 'w-5 h-5',
  md: 'w-8 h-8',
  lg: 'w-12 h-12',
  xl: 'w-20 h-20',
};

function SpinnerInner({ size = 'md', text, fullScreen = false }: SpinnerProps) {
  const sizeClass = sizeClasses[size];

  const content = (
    <>
      <Loader2 className={`animate-spin text-emerald-400 ${sizeClass}`} />
      {text && <p className="text-white/50 text-sm mt-3 font-medium">{text}</p>}
    </>
  );

  if (fullScreen) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gradient-to-br from-[#0a0a0f] via-[#0a0a0f] to-[#1a1a2e]">
        {content}
      </div>
    );
  }

  return (
    <div className="flex flex-col items-center justify-center py-12">
      {content}
    </div>
  );
}

export const PageSpinner = memo(() => (
  <SpinnerInner size="lg" text="Loading..." fullScreen />
));

export const SmallSpinner = memo(() => (
  <SpinnerInner size="sm" />
));

export const MediumSpinner = memo(() => (
  <SpinnerInner size="md" />
));

export const LargeSpinner = memo(() => (
  <SpinnerInner size="xl" text="Loading..." />
));

// Skeleton loader for rows
export function RowSkeleton({ count = 8 }: { count?: number }) {
  return (
    <div className="py-6">
      <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6">
        <div className="h-6 w-48 bg-white/5 rounded animate-pulse mb-4" />
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-8 gap-3">
          {Array.from({ length: count }).map((_, i) => (
            <div key={i} className="aspect-[2/3] rounded-xl bg-white/5 animate-pulse" />
          ))}
        </div>
      </div>
    </div>
  );
}

export default memo(SpinnerInner);
